import{z as B,x as l,o as t,c,q as o,j as A,D as e,d as E,s as i,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"OAuth 攻击面","description":"","frontmatter":{"title":"OAuth 攻击面","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/oauth-attack-surface.md","filePath":"cs/oauth-attack-surface.md","lastUpdated":1791413859000}'),d={name:"cs/oauth-attack-surface.md"};function p(u,a,h,C,D,m){const s=l("Mermaid");return t(),c("div",null,[a[2]||(a[2]=o('<h1 id="oauth-攻击面" tabindex="-1">OAuth 攻击面 <a class="header-anchor" href="#oauth-攻击面" aria-label="Permalink to &quot;OAuth 攻击面&quot;">​</a></h1><div class="epigraph"><p>OAuth 让客户端在用户同意下访问资源服务器，本身不是登录协议。重定向 URI、state、PKCE、混淆代理，决定这次同意是否被掉包。</p><footer>—— RFC 6749；RFC 8252；RFC 6819；RFC 7636 PKCE</footer></div><p>上一课<a href="/cs/session-management">会话</a>管的是第一方会话。本课补<strong>委托授权</strong>：第三方应用拿到的应是访问令牌，而不是用户口令。注意 OAuth 本身不是登录协议，当登录用需要 OpenID Connect。本课先收授权码流的攻击面，不给钓鱼操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把攻击面按授权码流的环节数下来：授权服务器的重定向端点若接受外部 URL，授权码就送到攻击者手里；缺 state，浏览器会在用户不知情下替攻击者完成「同意」，属 CSRF 式绑定；公客户端（存不住密钥）缺 PKCE，被截的码可换令牌；令牌进了 URL 前段就落进日志与 Referer；scope 给得过宽，一次泄漏等于全部权限。缺口集中在重定向与客户端档案两处，不是再讲「社交登录」产品。</p><p><span class="marginnote">常见误区：初学者容易把「用 GitHub 登录」当成 OAuth 的本职。实际上 OAuth 只管委托授权（发访问令牌）；「登录」是 OIDC 在它上面补了身份令牌才实现的能力，拿裸 OAuth 当登录用是经典错位。</span></p><h3 id="access-token-当会话" tabindex="-1">access token 当会话 <a class="header-anchor" href="#access-token-当会话" aria-label="Permalink to &quot;access token 当会话&quot;">​</a></h3><p>常见误用是把 access token 当会话。资源服务器必须验 aud 与签名（或走内省端点），确认令牌真是发给自己的；把令牌当不透明 cookie 到处存，会回到 JWT 课的陷阱——但没有那课的验签纪律。</p><p><span class="marginnote">RFC 6819 威胁模型。PKCE 原为公客户端，现成建议默认。本课禁止配置恶意客户端的教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把检查点钉在流的每一环：客户端注册时 redirect_uri 精确匹配；授权请求带 state，OIDC 再加 nonce；公客户端一律 PKCE；令牌交换走后信道，不经过前端；scope 按需最小授予。对照隐式流为何退出：它把令牌直接放进 URL 前段，泄漏面无法收敛，已被 OAuth 2.1 弃用。SAML 下一课，是企业里另一套 XML 委托。</p><p><span class="marginnote">术语翻译：PKCE 就是给授权码配的「防掉包暗号」——发起请求时留下暗号的指纹（challenge），换令牌时必须出示原话（verifier）。攻击者截到码却没有暗号原话，拿去授权服务器也换不出令牌。</span></p>',13)),(t(),A(n,null,{default:e(()=>[i(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20UA%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%22%5D%20--%3E%20AS%5B%22%E6%8E%88%E6%9D%83%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A%20%20AS%20--%3E%20CODE%5B%22%E6%8E%88%E6%9D%83%E7%A0%81%E5%9B%9E%20redirect%22%5D%0A%20%20CODE%20--%3E%20PKCE%5B%22%E7%A0%81%2Bverifier%20%E6%8D%A2%E4%BB%A4%E7%89%8C%22%5D%0A%20%20PKCE%20--%3E%20RS%5B%22%E8%B5%84%E6%BA%90%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"机制上，委托把授权服务器做成了 TCB：客户端不再经手口令，但每一处绑定都要对准——授权码绑定到发起的客户端（PKCE/state）、码只能配注册过的 redirect、令牌绑定到预期 aud。三处绑定任一松弛，「同意」就被掉包。下一课 SAML：断言与 XML 包装是同类绑定问题。",-1)),(t(),A(n,null,{default:e(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CODE%5B%22%E6%8E%88%E6%9D%83%E7%A0%81%E5%88%B0%E8%BE%BE%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20B1%5B%22%E7%BB%91%E5%AE%9A%E4%B8%80%20state%20%E4%B8%8E%20PKCE%20%E9%94%81%E5%8F%91%E8%B5%B7%E6%96%B9%22%5D%0A%20%20CODE%20--%3E%20B2%5B%22%E7%BB%91%E5%AE%9A%E4%BA%8C%20redirect_uri%20%E7%B2%BE%E7%A1%AE%E5%8C%B9%E9%85%8D%22%5D%0A%20%20CODE%20--%3E%20B3%5B%22%E7%BB%91%E5%AE%9A%E4%B8%89%20aud%20%E9%94%81%E7%9B%AE%E6%A0%87%E8%B5%84%E6%BA%90%22%5D%0A%20%20B1%20-.%20%E7%BC%BA%E5%A4%B1%20.-%3E%20X1%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E6%9B%BF%E6%94%BB%E5%87%BB%E8%80%85%E5%AE%8C%E6%88%90%E5%90%8C%E6%84%8F%22%5D%0A%20%20B2%20-.%20%E6%9D%BE%E5%BC%9B%20.-%3E%20X2%5B%22%E7%A0%81%E8%A2%AB%E9%80%81%E5%88%B0%E6%94%BB%E5%87%BB%E8%80%85%E7%AB%99%E7%82%B9%22%5D%0A%20%20B3%20-.%20%E4%B8%8D%E9%AA%8C%20.-%3E%20X3%5B%22%E4%BB%A4%E7%89%8C%E8%A2%AB%E5%8F%91%E9%94%99%E7%9A%84%E6%9C%8D%E5%8A%A1%E6%94%B6%E4%B8%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">直觉类比：state 就像寄快递用的取件码——你发起授权时随手生成一串只有自己知道的号码，回调时必须原样带回来。对不上号，就说明这次「同意」不是你发起的那一次，直接丢弃。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 grant 类型，设备流、客户端凭证从略。SAML 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>会话管第一方，OAuth 管第三方委托。</li><li>redirect_uri、state、PKCE、scope 是四条合同线。</li><li>OAuth 不是登录；带身份令牌的是 OIDC。</li><li>下一课 SAML。</li><li>出处：RFC 6749；RFC 6819；RFC 7636；RFC 8252。</li></ul>',5))])}const P=B(d,[["render",p]]);export{_ as __pageData,P as default};
